\$ok=\$true
Get-ChildItem -Recurse -Filter *.ps1 | ForEach-Object {
  \$errs=\$null
  [void][System.Management.Automation.Language.Parser]::ParseFile(\$_.FullName,[ref]\$null,[ref]\$errs)
  if (\$errs) { \$ok=\$false; Write-Host (\"PARSE ERROR: \" + \$_.Name); \$errs | ForEach-Object { Write-Host \$_.Message } }
  else { Write-Host (\"OK: \" + \$_.FullName.Substring((Get-Location).Path.Length+1)) }
}
if (\$ok) { 'ALL PARSE OK' }
" && echo "" && echo "=== actionlint ===" && actionlint .github/workflows/semantic-version-bumper.yml && echo "actionlint exit=$?"

